function solarLayout(s){
 const bodies=systemBodies(s),stations=stationRecords(s).filter(b=>b.visibility==='system'||(!b.visibility&&b.important!==false)),entities=entityRecords(s),planets=bodies.filter(b=>b.type==='World'),used=new Set(planets.filter(b=>b.slot).map(b=>b.slot));
 const seed=Array.from(s.name).reduce((a,c)=>a+c.charCodeAt(0),0);
 const assigned=planets.map((b,i)=>{let slot=b.slot||b.diagramSlot;if(!slot){slot=s.centralBodyType==='black-hole'?i+1:2+i*2;while(used.has(slot))slot++;used.add(slot)}return {...b,layoutSlot:slot,confirmed:!!b.slot,synthetic:false}});
 const maxSlot=Math.max(0,...assigned.map(b=>b.layoutSlot)),total=s.schematicPlanets?Math.max(maxSlot,...Object.keys(s.schematicPlanets).map(Number),...stations.map(b=>Math.ceil(b.lane||0)),...entities.map(b=>Math.ceil(b.lane||0))):s.sparseOrbits?Math.max(maxSlot,...stations.map(b=>Math.ceil(b.lane||0)),...entities.map(b=>Math.ceil(b.lane||0))):(s.centralBodyType==='black-hole'||EXOTIC_TYPES[s.centralBodyType])?maxSlot:s.kind==='uncertain'&&!planets.length?0:Math.max(5+seed%3,maxSlot+2,...stations.map(b=>Math.ceil(b.lane||0)));
 const orbits=[];for(let slot=1;slot<=total;slot++){const known=assigned.filter(b=>b.layoutSlot===slot);if(known.length)orbits.push(...known);else if(s.schematicPlanets){const kind=s.schematicPlanets[slot];if(kind)orbits.push(illustrativePlanet(slot,kind))}else if(!s.sparseOrbits){const kind=slot>=total-1?['icy','gas','ice-giant','ringed'][(slot+seed)%4]:['rocky','cinder','desert'][(slot+seed)%3];orbits.push(illustrativePlanet(slot,kind))}}
 return {orbits:s.sparseOrbits?orbits.filter(b=>!b.synthetic):orbits,entities,moons:bodies.filter(b=>b.type==='Moon'),sites:bodies.filter(b=>!['World','Moon'].includes(b.type)),stations,total,seed};
}
